css:
/* Thread 3 hero sprite - archetype: TRANSFORM, 32 frames, 5x7 grid, native ratio 3:2 */
.hero-sprite {
  aspect-ratio: 3 / 2;
  width: min(90vw, 1200px);
  height: auto;
  margin: 0 auto;
  background-image: url('sprite.webp');
  background-repeat: no-repeat;
  background-size: 500% 700%; /* percentage, not px - required, see this project's own bleed-bug finding */
  background-position: 25% 50%; /* unconditional base state: the chosen fallback frame's grid cell (1,3), frame index 16 - per-archetype choice (src/archetypes.js), not always the last frame and NOT always "100% 100%" even when it is, since frameCount doesn't always fill the grid exactly */
}

@supports (animation-timeline: scroll()) {
  .hero-sprite {
    animation: hero-scrub-transform linear both;
    animation-timeline: scroll(root block);
  }
}

@keyframes hero-scrub-transform {
  0.000% { background-position: 0% 0%; animation-timing-function: steps(1, jump-end); }
  3.226% { background-position: 25% 0%; animation-timing-function: steps(1, jump-end); }
  6.452% { background-position: 50% 0%; animation-timing-function: steps(1, jump-end); }
  9.677% { background-position: 75% 0%; animation-timing-function: steps(1, jump-end); }
  12.903% { background-position: 100% 0%; animation-timing-function: steps(1, jump-end); }
  16.129% { background-position: 0% 16.667%; animation-timing-function: steps(1, jump-end); }
  19.355% { background-position: 25% 16.667%; animation-timing-function: steps(1, jump-end); }
  22.581% { background-position: 50% 16.667%; animation-timing-function: steps(1, jump-end); }
  25.806% { background-position: 75% 16.667%; animation-timing-function: steps(1, jump-end); }
  29.032% { background-position: 100% 16.667%; animation-timing-function: steps(1, jump-end); }
  32.258% { background-position: 0% 33.333%; animation-timing-function: steps(1, jump-end); }
  35.484% { background-position: 25% 33.333%; animation-timing-function: steps(1, jump-end); }
  38.710% { background-position: 50% 33.333%; animation-timing-function: steps(1, jump-end); }
  41.935% { background-position: 75% 33.333%; animation-timing-function: steps(1, jump-end); }
  45.161% { background-position: 100% 33.333%; animation-timing-function: steps(1, jump-end); }
  48.387% { background-position: 0% 50%; animation-timing-function: steps(1, jump-end); }
  51.613% { background-position: 25% 50%; animation-timing-function: steps(1, jump-end); }
  54.839% { background-position: 50% 50%; animation-timing-function: steps(1, jump-end); }
  58.065% { background-position: 75% 50%; animation-timing-function: steps(1, jump-end); }
  61.290% { background-position: 100% 50%; animation-timing-function: steps(1, jump-end); }
  64.516% { background-position: 0% 66.667%; animation-timing-function: steps(1, jump-end); }
  67.742% { background-position: 25% 66.667%; animation-timing-function: steps(1, jump-end); }
  70.968% { background-position: 50% 66.667%; animation-timing-function: steps(1, jump-end); }
  74.194% { background-position: 75% 66.667%; animation-timing-function: steps(1, jump-end); }
  77.419% { background-position: 100% 66.667%; animation-timing-function: steps(1, jump-end); }
  80.645% { background-position: 0% 83.333%; animation-timing-function: steps(1, jump-end); }
  83.871% { background-position: 25% 83.333%; animation-timing-function: steps(1, jump-end); }
  87.097% { background-position: 50% 83.333%; animation-timing-function: steps(1, jump-end); }
  90.323% { background-position: 75% 83.333%; animation-timing-function: steps(1, jump-end); }
  93.548% { background-position: 100% 83.333%; animation-timing-function: steps(1, jump-end); }
  96.774% { background-position: 0% 100%; animation-timing-function: steps(1, jump-end); }
  100.000% { background-position: 25% 100%; }
}

@media (prefers-reduced-motion: reduce) {
  .hero-sprite {
    animation: none !important;
    background-position: 25% 50%;
  }
}
